// Step 1: Verify commit exists and list scoped files
const commit = await Bun.$`git show --stat 168f583 --oneline`.quiet();
console.log('=== COMMIT ===');
console.log(commit.stdout.toString());

import fs from 'fs';

const files = [
  'index.ts',
  'src/types.ts',
  'src/config.ts',
  'src/governor.ts',
  'src/core.ts',
  'test/governor.test.ts',
  'test/core.test.ts',
  'scripts/behavioral-parcour/c02_runner.py',
  'scripts/behavioral-parcour/test_c02_runner.py',
  'scripts/behavioral-parcour/c02-supersession-corpus.json',
  'scripts/behavioral-parcour/c02-contract-files.json',
  'docs/c02-fresh-supersession-preregistration.md',
];

for (const f of files) {
  console.log(`\n========== ${f} ==========`);
  try {
    const content = fs.readFileSync(f, 'utf-8');
    // Print with line numbers
    content.split('\n').forEach((line, i) => {
      console.log(`${(i+1).toString().padStart(4)} | ${line}`);
    });
  } catch (e) {
    console.log(`ERROR: ${e.message}`);
  }
}

