  19 | import { callModelWithAuth } from "./src/model.js";
  20 | import { DEFAULT_CONFIG, parseModelRef } from "./src/config.js";
  21 | import { buildUserContext, buildUserContextFromMessages } from "./src/context.js";
  22 | import { ConsortiumLogger, createProgressCallback, formatVisibleMessage } from "./src/ui.js";
  23 | import type { ConsortiumConfig, TurnState, DeliberationResult, GovernorMode, TelemetryEvent } from "./src/types.js";
  24 | import { createUsageAccumulator, buildDeliberationTelemetry, safeLog } from "./src/telemetry.js";
  25 | import { join, dirname } from "node:path";
  26 | import { readFile, writeFile, rename, mkdir } from "node:fs/promises";
  27 | import { existsSync } from "node:fs";
  28 | 
  29 | export default function (pi: ExtensionAPI): void {
  30 |   let enabled = true;
  31 |   let governorMode: GovernorMode = "smart_extractor";
  32 |   let maxTurnGap = 20;
  33 |   let periodicInterval = 10;
  34 |   let stateSupersessionGuard = false;
  35 |   let turnsSinceLastAudit = 0;
  36 | 
  37 |   let turnState: TurnState = { deliberation: null };
  38 |   let lastExtractedContext: DeliberationResult["extractedContext"] | null = null;
  39 |   let logger: ConsortiumLogger | null = null;
  40 | 
  41 |   // Queue writes sequentially to prevent race conditions between rapid toggles.
  42 |   let persistPending: Promise<void> = Promise.resolve();
  43 | 
  44 |   async function persistSettings(
  45 |     cwd: string,
  46 |     opts: { enabled?: boolean; governorMode?: GovernorMode; maxTurnGap?: number; periodicInterval?: number; stateSupersessionGuard?: boolean },
  47 |   ): Promise<void> {
  48 |     persistPending = persistPending.then(async () => {
  49 |       try {
  50 |         const dir = join(cwd, ".pi");
  51 |         try {
  52 |           await mkdir(dir, { recursive: true });
  53 |         } catch {
  54 |           // Directory exists or mkdir failed.
  55 |         }
  56 |         const p = join(dir, "settings.json");
  57 |         const tmp = p + ".tmp";
  58 |         let s: Record<string, unknown> = {};
  59 |         if (existsSync(p)) {
  60 |           try {
  61 |             const raw = await readFile(p, "utf-8");
  62 |             s = JSON.parse(raw);
  63 |           } catch {
  64 |             // Corrupted file — overwrite.
  65 |           }
  66 |         }
  67 | 
  68 |         let existingConsortium: Record<string, unknown> = {};
  69 |         if (typeof s.consortium === "object" && s.consortium !== null) {
  70 |           existingConsortium = s.consortium as Record<string, unknown>;
  71 |         } else if (typeof s.consortium === "boolean") {
  72 |           existingConsortium = { enabled: s.consortium };
  73 |         }
  74 | 
  75 |         s.consortium = {
  76 |           enabled: opts.enabled !== undefined ? opts.enabled : (existingConsortium.enabled ?? enabled),
  77 |           governorMode: opts.governorMode !== undefined ? opts.governorMode : (existingConsortium.governorMode ?? governorMode),
  78 |           maxTurnGap: opts.maxTurnGap !== undefined ? opts.maxTurnGap : (existingConsortium.maxTurnGap ?? maxTurnGap),
  79 |           periodicInterval: opts.periodicInterval !== undefined ? opts.periodicInterval : (existingConsortium.periodicInterval ?? periodicInterval),
  80 |           stateSupersessionGuard: opts.stateSupersessionGuard !== undefined ? opts.stateSupersessionGuard : (existingConsortium.stateSupersessionGuard ?? stateSupersessionGuard),
  81 |         };
  82 | 
  83 |         await writeFile(tmp, JSON.stringify(s, null, 2) + "\n");
  84 |         await rename(tmp, p);
  85 |       } catch {
  86 |         // Best-effort persistence.
  87 |       }
  88 |     });
  89 |     await persistPending;
  90 |   }
  91 | 
  92 |   pi.on("session_start", async (_event, ctx) => {
  93 |     try {
  94 |       const p = join(ctx.cwd, ".pi", "settings.json");
  95 |       if (!existsSync(p)) return;
  96 |       const raw = await readFile(p, "utf-8");
  97 |       const s = JSON.parse(raw);
  98 |       if (typeof s.consortium === "boolean") {
  99 |         enabled = s.consortium;
 100 |       } else if (typeof s.consortium === "object" && s.consortium !== null) {
 101 |         if (s.consortium.enabled !== undefined) enabled = !!s.consortium.enabled;
 102 |         if (s.consortium.governorMode !== undefined) governorMode = s.consortium.governorMode as GovernorMode;
 103 |         if (typeof s.consortium.maxTurnGap === "number") maxTurnGap = s.consortium.maxTurnGap;
 104 |         if (typeof s.consortium.periodicInterval === "number") periodicInterval = s.consortium.periodicInterval;
 105 |         if (typeof s.consortium.stateSupersessionGuard === "boolean") stateSupersessionGuard = s.consortium.stateSupersessionGuard;
 106 |       }
 107 |       if (!enabled && ctx.hasUI) {
 108 |         ctx.ui.setStatus("consortium", "consortium: disabled");
 109 |       }
 110 |     } catch {
 111 |       // Default to enabled — fail open for safety.
 112 |     }
 113 |   });
