 122 |   pi.on("input", async (event: InputEvent, ctx: ExtensionContext) => {
 123 |     const userContext = buildUserContext(event, ctx);
 124 | 
 125 |     // Initialize logger once per session
 126 |     if (!logger) {
 127 |       logger = new ConsortiumLogger(ctx.cwd, ctx.sessionManager.getSessionId());
 128 |     }
 129 |     logger.log({ type: "turn_start", input: userContext });
 130 | 
 131 |     return { action: "continue" };
 132 |   });
 133 | 
 134 |   // On first LLM call of the turn, await deliberation and inject.
 135 |   pi.on("context", async (event: ContextEvent, ctx: ExtensionContext) => {
 136 |     if (!enabled) {
 137 |       if (ctx.hasUI) {
 138 |         ctx.ui.setStatus("consortium", "consortium: disabled");
 139 |       }
 140 |       return;
 141 |     }
 142 |     if (turnState.deliberation) {
 143 |       return;
 144 |     }
 145 | 
 146 |     const userContext = buildUserContextFromMessages(event.messages);
 147 |     if (!userContext) {
 148 |       return;
 149 |     }
 150 | 
 151 |     if (!logger) {
 152 |       logger = new ConsortiumLogger(ctx.cwd, ctx.sessionManager.getSessionId());
 153 |     }
 154 | 
 155 |     const onProgress = createProgressCallback(ctx);
 156 |     const runtimeConfig = {
 157 |       ...DEFAULT_CONFIG,
 158 |       governorMode,
 159 |       maxTurnGap,
 160 |       periodicInterval,
 161 |       stateSupersessionGuard,
 162 |     };
 163 | 
 164 |     turnState.deliberation = runDeliberation(runtimeConfig, event.messages, ctx, logger, onProgress, turnsSinceLastAudit, lastExtractedContext !== null);
 165 | 
 166 |     try {
 167 |       const result = await turnState.deliberation;
 168 | 
 169 |       if (result.skippedByGovernor) {
 170 |         turnState.deliberation = null;
 171 |         lastExtractedContext = result.extractedContext ?? null;
 172 |         turnsSinceLastAudit++;
 173 |         if (result.extractedContext) {
 174 |           logger?.logExtraction(result.extractedContext);
 175 |         }
 176 |         logger?.log({
 177 |           type: "injection_skipped",
 178 |           reason: result.governorReason || "SKIPPED_BY_GOVERNOR",
 179 |           probe_count: 0,
 180 |           extractedContext: result.extractedContext,
 181 |         });
 182 |         if (ctx.hasUI) {
 183 |           ctx.ui.setStatus("consortium", "consortium: ⏭ skipped");
 184 |           ctx.ui.notify(formatVisibleMessage(result), "info");
 185 |         }
 186 |         return;
 187 |       }
 188 | 
 189 |       // Full probe audit ran — reset turn counter gap
 190 |       turnsSinceLastAudit = 0;
 191 | 
 192 |       if (result.synthesis.trim().startsWith("NO_CONTRIBUTION")) {
 193 |         turnState.deliberation = null;
 194 |         lastExtractedContext = result.extractedContext ?? null;
 195 |         if (result.extractedContext) {
 196 |           logger?.logExtraction(result.extractedContext);
 197 |         }
 198 |         logger?.log({
 199 |           type: "injection_skipped",
 200 |           reason: "NO_CONTRIBUTION",
 201 |           probe_count: result.probes.length,
 202 |           extractedContext: result.extractedContext,
 203 |         });
 204 |         if (ctx.hasUI) {
 205 |           ctx.ui.setStatus("consortium", "consortium: ✓ complete (nothing to add)");
 206 |           ctx.ui.notify(formatVisibleMessage(result), "info");
 207 |         }
 208 |         return;
 209 |       }
 210 | 
 211 |       const syntheticMessage: AgentMessage = {
 212 |         role: "user",
 213 |         content: `[CONSORTIUM DELIBERATION]\n\n${result.synthesis}`,
 214 |         timestamp: Date.now(),
 215 |       };
 216 | 
 217 |       const messages = [...event.messages];
 218 |       messages.push(syntheticMessage);
 219 |       turnState.deliberation = null;
 220 |       lastExtractedContext = result.extractedContext ?? null;
 221 |       if (result.extractedContext) {
 222 |         logger?.logExtraction(result.extractedContext);
 223 |       }
 224 | 
 225 |       logger?.log({
 226 |         type: "injection_complete",
 227 |         synthesis_length: result.synthesis.length,
 228 |         probe_count: result.probes.length,
 229 |         errors: result.errors,
 230 |         governor_reason: result.governorReason,
 231 |         probes: result.probes,
 232 |         synthesis: result.synthesis,
 233 |         extractedContext: result.extractedContext,
 234 |       });
 235 | 
 236 |       // Persist in session JSONL
 237 |       try {
 238 |         pi.appendEntry(CUSTOM_TYPE, {
 239 |           schemaVersion: "0.1",
 240 |           kind: "deliberation",
 241 |           synthesis: result.synthesis,
 242 |           probe_count: result.probes.length,
 243 |           extractedContext: result.extractedContext,
 244 |           errors: result.errors,
 245 |         });
 246 |       } catch {
 247 |         // Some modes don't support session append.
 248 |       }
 249 | 
 250 |       // Visible TUI notification
 251 |       if (ctx.hasUI) {
 252 |         ctx.ui.notify(formatVisibleMessage(result), result.errors?.length ? "warning" : "info");
 253 |       }
 254 | 
 255 |       if (result.errors) {
 256 |         if (ctx.hasUI) {
 257 |           ctx.ui.setStatus("consortium", `consortium: ⚠ ${result.errors.length} error(s)`);
 258 |         }
 259 |       } else {
 260 |         if (ctx.hasUI) {
 261 |           ctx.ui.setStatus("consortium", "consortium: ✓ complete");
 262 |         }
 263 |       }
 264 | 
 265 |       return { messages };
 266 |     } catch (err) {
 267 |       const msg = err instanceof Error ? err.message : String(err);
 268 |       logger?.log({ type: "deliberation_failed", error: msg });
 269 |       if (ctx.hasUI) {
 270 |         ctx.ui.setStatus("consortium", `consortium: ✖ failed: ${msg}`);
 271 |       }
 272 |       turnState.deliberation = null;
 273 |       return;
 274 |     }
 275 |   });
