 386 | /** Run the full deliberation cycle. */
 387 | export async function runDeliberation(
 388 |   baseConfig: typeof DEFAULT_CONFIG,
 389 |   input: string | AgentMessage[],
 390 |   ctx: ExtensionContext,
 391 |   logger: ConsortiumLogger,
 392 |   onProgress: (phase: string, current: number, total: number, role?: string) => void,
 393 |   turnsSinceLastAudit: number,
 394 |   baselineAvailable: boolean,
 395 | ): Promise<DeliberationResult> {
 396 |   const deliberationModel = resolveDeliberationModel(ctx);
 397 |   const modelRegistry = ctx.modelRegistry;
 398 | 
 399 |   const config: ConsortiumConfig = {
 400 |     ...baseConfig,
 401 |     probes: baseConfig.probes.map((p) => ({
 402 |       ...p,
 403 |       provider: deliberationModel.provider,
 404 |       modelId: deliberationModel.id,
 405 |     })),
 406 |     synthesis: {
 407 |       ...baseConfig.synthesis,
 408 |       provider: deliberationModel.provider,
 409 |       modelId: deliberationModel.id,
 410 |     },
 411 |     extraction: baseConfig.extraction
 412 |       ? {
 413 |           ...baseConfig.extraction,
 414 |           provider: deliberationModel.provider,
 415 |           modelId: deliberationModel.id,
 416 |         }
 417 |       : undefined,
 418 |   };
 419 | 
 420 |   logger.log({
 421 |     type: "deliberation_start",
 422 |     model: `${deliberationModel.provider}/${deliberationModel.id}`,
 423 |     modelSource: deliberationModel.source,
 424 |     probe_count: config.probes.length,
 425 |   });
 426 | 
 427 |   // ── Telemetry state (local to this runDeliberation call) ──
 428 |   const acc = createUsageAccumulator();
 429 |   let baselineSupplied: boolean | undefined;
 430 |   const telemetryLog = (event: TelemetryEvent): void => {
 431 |     logger.log(event);
 432 |   };
 433 | 
 434 |   const onBaselineCheck = (bs: boolean): void => {
 435 |     baselineSupplied = bs;
 436 |     safeLog(telemetryLog, { type: "baseline_check", baseline_available: baselineAvailable, baseline_supplied: bs });
 437 |   };
 438 | 
 439 |   const callModel: ModelCallFn = async (modelKey, system, user, _maxTokens, _temperature, signal) => {
 440 |     const start = Date.now();
 441 |     const { provider, modelId, role } = resolveModelKey(modelKey, config);
 442 | 
 443 |     logger.log({
 444 |       type: "probe_start",
 445 |       modelKey,
 446 |       role: role ?? undefined,
 447 |       provider,
 448 |       modelId,
 449 |       system_prompt: system,
 450 |       user_input: user,
 451 |     });
 452 | 
 453 |     try {
 454 |       const result = await callModelWithAuth(provider, modelId, system, user, modelRegistry, signal);
 455 |       const duration = Date.now() - start;
 456 |       const usageReported = result.usage !== null;
 457 | 
 458 |       // Record usage in accumulator
 459 |       if (result.usage !== null) {
 460 |         acc.addReported(result.usage);
 461 |       } else {
 462 |         acc.addUnreported();
 463 |       }
 464 | 
 465 |       // Log probe_complete with usage_reported flag
 466 |       const logEntry: Record<string, unknown> = {
 467 |         type: "probe_complete",
 468 |         modelKey,
 469 |         role: role ?? undefined,
 470 |         duration_ms: duration,
 471 |         output_length: result.text.length,
 472 |         output: result.text,
 473 |         usage_reported: usageReported,
 474 |       };
 475 |       if (result.usage !== null) {
 476 |         logEntry.usage = result.usage;
 477 |       }
 478 |       logger.log(logEntry);
 479 | 
 480 |       return result.text;
 481 |     } catch (err) {
 482 |       const duration = Date.now() - start;
 483 |       const msg = err instanceof Error ? err.message : String(err);
 484 |       logger.log({ type: "probe_error", modelKey, duration_ms: duration, error: msg });
 485 |       throw err;
 486 |     }
 487 |   };
 488 | 
 489 |   const core = new ConsortiumCore(config, callModel, onBaselineCheck);
 490 |   const result = await core.deliberate(input, ctx.signal, onProgress, turnsSinceLastAudit);
 491 | 
 492 |   // ── Final deliberation_telemetry (after core completes) ──
 493 |   const finalEvent = buildDeliberationTelemetry(baselineAvailable, baselineSupplied, acc);
 494 |   safeLog(telemetryLog, finalEvent);
 495 | 
 496 |   return result;
 497 | }
 498 | 
 499 | /** Resolve provider + modelId from a modelKey string. */
 500 | function resolveModelKey(
 501 |   modelKey: string,
 502 |   config: ConsortiumConfig,
 503 | ): { provider: string; modelId: string; role?: string } {
 504 |   if (modelKey === "synthesis") {
 505 |     return { provider: config.synthesis.provider, modelId: config.synthesis.modelId };
 506 |   }
 507 |   if (modelKey === "extraction") {
 508 |     if (config.extraction) {
 509 |       return { provider: config.extraction.provider, modelId: config.extraction.modelId };
 510 |     }
 511 |     return { provider: config.synthesis.provider, modelId: config.synthesis.modelId };
 512 |   }
 513 |   const match = modelKey.match(/^probe:(\d+)(?::(.+))?$/);
 514 |   if (match) {
 515 |     const i = parseInt(match[1], 10);
 516 |     const probe = config.probes[i];
 517 |     if (!probe) {
 518 |       throw new Error(`Probe ${i} not found in config`);
 519 |     }
 520 |     return { provider: probe.provider, modelId: probe.modelId, role: match[2] ?? probe.role };
 521 |   }
 522 |   throw new Error(`Unknown modelKey: "${modelKey}"`);
 523 | }

========== src/types.ts ==========
   1 | // Consortium types — pure interfaces, no runtime dependencies.
   2 | 
   3 | /** High-level strategic context vectors extracted from session history. */
   4 | export interface ExtractedContext {
   5 |   /** 1. Macro goals, technical criteria, and quality expectations set by user. */
   6 |   userRequirements: string[];
   7 |   /** 2. Explicit required architectural artifacts, files, or reports expected. */
   8 |   deliverables: string[];
   9 |   /** 3. Directions, goals, or constraints that were canceled, updated, or superseded. */
  10 |   revisedOrSupersededDirection: string[];
  11 |   /** 4. Confirmed user decisions, approved trade-offs, and design preferences. */
  12 |   userDecisions: string[];
  13 |   /** 5. High-level domain ambiguities or unaddressed user questions requiring clarification. */
  14 |   questionsAndInformationGaps: string[];
  15 |   /** 6. Active session rules, allowed path boundaries, and mode flags. */
  16 |   controlBoundaries: string[];
  17 |   /** 7. Verified milestone progress achieved so far (high-level, not individual tool calls). */
  18 |   observedWork: string[];
  19 |   /** 8. Verified domain truths, system behaviors, and test outcomes observed in logs. */
  20 |   observedCriticalFacts: string[];
  21 |   /** 9. Systemic insights, structural architecture patterns, or project rules learned. */
  22 |   relevantLearnings: string[];
  23 |   /** Signal from context extraction pass whether full probe deliberation is recommended. */
