 167 |   private async runProbes(
 168 |     userContext: string,
 169 |     signal: AbortSignal,
 170 |     errors: string[],
 171 |     onProgress?: ProgressCallback,
 172 |     probeTotal?: number,
 173 |   ): Promise<ProbeResult[]> {
 174 |     const mode = this.config.executionMode ?? "serial";
 175 | 
 176 |     if (mode === "serial") {
 177 |       return this.runProbesSerial(userContext, signal, errors, onProgress, probeTotal);
 178 |     }
 179 | 
 180 |     return this.runProbesParallel(userContext, signal, errors, onProgress, probeTotal);
 181 |   }
