 183 |   private async runProbesParallel(
 184 |     userContext: string,
 185 |     signal: AbortSignal,
 186 |     errors: string[],
 187 |     onProgress?: ProgressCallback,
 188 |     probeTotal?: number,
 189 |   ): Promise<ProbeResult[]> {
 190 |     let completed = 0;
 191 | 
 192 |     const probePromises = this.config.probes.map(async (probe, i) => {
 193 |       const probeController = new AbortController();
