 366 | /** Resolve the deliberation model from CONSORTIUM_MODEL env var, falling back to ctx.model. */
 367 | function resolveDeliberationModel(
 368 |   ctx: ExtensionContext,
 369 | ): { provider: string; id: string; source: string } {
 370 |   const ref = parseModelRef(process.env.CONSORTIUM_MODEL);
 371 |   if (ref) {
 372 |     const model = ctx.modelRegistry.find(ref.provider, ref.modelId);
 373 |     if (model) {
 374 |       return { provider: model.provider, id: model.id, source: "CONSORTIUM_MODEL" };
 375 |     }
 376 |     // Env var set but model not found — log warning and fall through
 377 |     console.warn(`[consortium] CONSORTIUM_MODEL="${process.env.CONSORTIUM_MODEL}" resolved but not found in model registry — falling back to executor model`);
 378 |   }
 379 |   // Fallback to executor model
 380 |   if (!ctx.model) {
 381 |     throw new Error("No active model available from ctx.model and CONSORTIUM_MODEL not resolvable");
 382 |   }
 383 |   return { provider: ctx.model.provider, id: ctx.model.id, source: "ctx.model" };
 384 | }
